/* ===========================
   Root & Global Styles
   =========================== */

:root {
    --color-primary: #2c2c2c;
    --color-secondary: #f5f3f0;
    --color-accent: #d4a574;
    --color-text: #1a1a1a;
    --color-text-light: #666;
    --color-border: #e0e0e0;
    --color-success: #2d9d5c;
    --color-danger: #d32f2f;
    --spacing-xs: 0.5rem;
    --spacing-sm: 1rem;
    --spacing-md: 1.5rem;
    --spacing-lg: 2rem;
    --spacing-xl: 3rem;
    --spacing-2xl: 4rem;
    --transition: 0.3s ease;
    --shadow-sm: 0 1px 3px rgba(0, 0, 0, 0.12);
    --shadow-md: 0 4px 12px rgba(0, 0, 0, 0.1);
    --shadow-lg: 0 8px 24px rgba(0, 0, 0, 0.15);
}

@media (prefers-reduced-motion: reduce) {
    :root {
        --transition: 0s;
    }
    * {
        animation-duration: 0.01ms !important;
        animation-iteration-count: 1 !important;
        transition-duration: 0.01ms !important;
    }
}

* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
}

html {
    scroll-behavior: smooth;
}

body {
    font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
    color: var(--color-text);
    background-color: #fff;
    line-height: 1.6;
    font-size: 1rem;
}

/* ===========================
   Accessibility
   =========================== */

.skip-link {
    position: absolute;
    top: -40px;
    left: 0;
    background: var(--color-primary);
    color: #fff;
    padding: var(--spacing-sm);
    text-decoration: none;
    z-index: 100;
    border-radius: 0 0 4px 0;
}

.skip-link:focus {
    top: 0;
}

.sr-only {
    position: absolute;
    width: 1px;
    height: 1px;
    padding: 0;
    margin: -1px;
    overflow: hidden;
    clip: rect(0, 0, 0, 0);
    white-space: nowrap;
    border-width: 0;
}

/* ===========================
   Typography
   =========================== */

h1, h2, h3, h4, h5, h6 {
    font-weight: 600;
    line-height: 1.2;
    margin-bottom: var(--spacing-sm);
    color: var(--color-primary);
}

h1 {
    font-size: 2.5rem;
}

h2 {
    font-size: 2rem;
}

h3 {
    font-size: 1.25rem;
}

p {
    margin-bottom: var(--spacing-sm);
    color: var(--color-text-light);
}

a {
    color: var(--color-primary);
    text-decoration: none;
    transition: color var(--transition);
}

a:hover {
    color: var(--color-accent);
}

a:focus-visible {
    outline: 2px solid var(--color-accent);
    outline-offset: 2px;
}

/* ===========================
   Buttons
   =========================== */

.btn {
    display: inline-block;
    padding: var(--spacing-sm) var(--spacing-lg);
    border: none;
    border-radius: 4px;
    font-size: 1rem;
    font-weight: 500;
    cursor: pointer;
    transition: all var(--transition);
    text-align: center;
    text-decoration: none;
    min-height: 44px;
    display: inline-flex;
    align-items: center;
    justify-content: center;
}

.btn:focus-visible {
    outline: 2px solid var(--color-accent);
    outline-offset: 2px;
}

.btn-primary {
    background-color: var(--color-primary);
    color: #fff;
}

.btn-primary:hover {
    background-color: #000;
    box-shadow: var(--shadow-md);
}

.btn-secondary {
    background-color: var(--color-secondary);
    color: var(--color-primary);
    border: 1px solid var(--color-border);
}

.btn-secondary:hover {
    background-color: #f0e8e0;
    border-color: var(--color-primary);
}

.btn-outline {
    background-color: transparent;
    color: var(--color-primary);
    border: 2px solid var(--color-primary);
}

.btn-outline:hover {
    background-color: var(--color-primary);
    color: #fff;
}

.icon-button {
    background: none;
    border: none;
    cursor: pointer;
    padding: var(--spacing-xs);
    display: flex;
    align-items: center;
    justify-content: center;
    color: var(--color-primary);
    transition: color var(--transition);
    min-height: 44px;
    min-width: 44px;
}

.icon-button:hover {
    color: var(--color-accent);
}

.icon-button:focus-visible {
    outline: 2px solid var(--color-accent);
    outline-offset: 2px;
}

/* ===========================
   Layout
   =========================== */

.section-container {
    max-width: 1200px;
    margin: 0 auto;
    padding: 0 var(--spacing-md);
}

.section-title {
    text-align: center;
    margin-bottom: var(--spacing-2xl);
    font-size: 2rem;
}

/* ===========================
   Header & Navigation
   =========================== */

.site-header {
    background-color: #fff;
    border-bottom: 1px solid var(--color-border);
    position: sticky;
    top: 0;
    z-index: 50;
    box-shadow: var(--shadow-sm);
}

.header-container {
    max-width: 1200px;
    margin: 0 auto;
    padding: var(--spacing-md);
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: var(--spacing-lg);
}

.logo h1 {
    font-size: 1.5rem;
    margin: 0;
    letter-spacing: -0.02em;
}

.primary-nav {
    flex: 1;
}

.menu-toggle {
    display: none;
    background: none;
    border: none;
    cursor: pointer;
    padding: var(--spacing-xs);
    color: var(--color-primary);
    min-height: 44px;
    min-width: 44px;
}

.menu-toggle:focus-visible {
    outline: 2px solid var(--color-accent);
    outline-offset: 2px;
}

.hamburger {
    display: block;
    width: 24px;
    height: 16px;
    position: relative;
}

.hamburger::before,
.hamburger::after,
.hamburger {
    content: '';
    display: block;
    height: 2px;
    background-color: var(--color-primary);
    transition: all var(--transition);
}

.hamburger::before {
    content: '';
    position: absolute;
    top: 0;
    left: 0;
}

.hamburger::after {
    content: '';
    position: absolute;
    bottom: 0;
    left: 0;
}

.menu-toggle[aria-expanded="true"] .hamburger {
    background-color: transparent;
}

.menu-toggle[aria-expanded="true"] .hamburger::before {
    transform: translateY(7px) rotate(45deg);
}

.menu-toggle[aria-expanded="true"] .hamburger::after {
    transform: translateY(-7px) rotate(-45deg);
}

.nav-menu {
    list-style: none;
    display: flex;
    gap: var(--spacing-lg);
    align-items: center;
}

.nav-link {
    font-weight: 500;
    color: var(--color-primary);
    transition: color var(--transition);
    display: inline-block;
    padding: var(--spacing-xs) 0;
    border-bottom: 2px solid transparent;
}

.nav-link:hover {
    color: var(--color-accent);
    border-bottom-color: var(--color-accent);
}

.header-actions {
    display: flex;
    gap: var(--spacing-md);
    align-items: center;
}

/* ===========================
   Hero Section
   =========================== */

.hero {
    background: linear-gradient(135deg, var(--color-secondary) 0%, #f0e8e0 100%);
    padding: var(--spacing-2xl) var(--spacing-md);
    text-align: center;
    min-height: 400px;
    display: flex;
    align-items: center;
    justify-content: center;
}

.hero-content h2 {
    font-size: 3rem;
    margin-bottom: var(--spacing-md);
    color: var(--color-primary);
}

.hero-content p {
    font-size: 1.25rem;
    margin-bottom: var(--spacing-lg);
    color: var(--color-text-light);
    max-width: 500px;
    margin-left: auto;
    margin-right: auto;
}

/* ===========================
   Products Grid
   =========================== */

.featured-section {
    padding: var(--spacing-2xl) var(--spacing-md);
}

.products-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
    gap: var(--spacing-lg);
}

.product-card {
    background: #fff;
    border: 1px solid var(--color-border);
    border-radius: 8px;
    overflow: hidden;
    transition: all var(--transition);
    display: flex;
    flex-direction: column;
    height: 100%;
}

.product-card:hover {
    box-shadow: var(--shadow-lg);
    transform: translateY(-4px);
}

.product-image {
    width: 100%;
    aspect-ratio: 3 / 3.5;
    background-color: var(--color-secondary);
    overflow: hidden;
}

.product-image img {
    width: 100%;
    height: 100%;
    object-fit: cover;
    transition: transform var(--transition);
}

.product-card:hover .product-image img {
    transform: scale(1.05);
}

.product-info {
    padding: var(--spacing-md);
    display: flex;
    flex-direction: column;
    flex: 1;
}

.product-name {
    font-size: 1.1rem;
    margin-bottom: var(--spacing-xs);
    font-weight: 600;
}

.product-category {
    font-size: 0.875rem;
    color: var(--color-text-light);
    margin-bottom: var(--spacing-sm);
}

.product-rating {
    display: flex;
    align-items: center;
    gap: var(--spacing-xs);
    margin-bottom: var(--spacing-sm);
    font-size: 0.875rem;
}

.stars {
    color: var(--color-accent);
    letter-spacing: 2px;
}

.rating-count {
    color: var(--color-text-light);
}

.product-pricing {
    margin-bottom: var(--spacing-md);
    flex-grow: 1;
    display: flex;
    align-items: flex-end;
}

.price {
    font-size: 1.25rem;
    font-weight: 600;
    color: var(--color-primary);
}

.btn-add-to-cart {
    width: 100%;
}

/* ===========================
   Deals Section
   =========================== */

.deals-section {
    padding: var(--spacing-2xl) var(--spacing-md);
    background-color: var(--color-secondary);
}

.deals-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
    gap: var(--spacing-lg);
}

.deal-card {
    background: #fff;
    border-radius: 8px;
    overflow: hidden;
    position: relative;
    transition: all var(--transition);
    box-shadow: var(--shadow-sm);
}

.deal-card:hover {
    box-shadow: var(--shadow-lg);
    transform: translateY(-4px);
}

.deal-badge {
    position: absolute;
    top: var(--spacing-sm);
    right: var(--spacing-sm);
    background-color: var(--color-danger);
    color: #fff;
    padding: var(--spacing-xs) var(--spacing-sm);
    border-radius: 4px;
    font-weight: 600;
    z-index: 10;
}

.deal-image {
    width: 100%;
    aspect-ratio: 1;
    background-color: #f5f5f5;
    overflow: hidden;
}

.deal-image img {
    width: 100%;
    height: 100%;
    object-fit: cover;
    transition: transform var(--transition);
}

.deal-card:hover .deal-image img {
    transform: scale(1.1);
}

.deal-info {
    padding: var(--spacing-md);
}

.deal-name {
    font-size: 1rem;
    font-weight: 600;
    margin-bottom: var(--spacing-sm);
}

.deal-pricing {
    display: flex;
    gap: var(--spacing-sm);
    align-items: center;
    margin-bottom: var(--spacing-md);
}

.price-original {
    color: var(--color-text-light);
    text-decoration: line-through;
    font-size: 0.9rem;
}

.price-sale {
    font-size: 1.25rem;
    font-weight: 600;
    color: var(--color-danger);
}

/* ===========================
   Editorial Section
   =========================== */

.editorial-section {
    padding: var(--spacing-2xl) var(--spacing-md);
}

.editorial-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
    gap: var(--spacing-lg);
}

.editorial-card {
    background: #fff;
    border-radius: 8px;
    overflow: hidden;
    transition: all var(--transition);
    box-shadow: var(--shadow-sm);
    border: 1px solid var(--color-border);
}

.editorial-card:hover {
    box-shadow: var(--shadow-lg);
}

.editorial-image {
    width: 100%;
    aspect-ratio: 4 / 3;
    overflow: hidden;
    background-color: var(--color-secondary);
}

.editorial-image img {
    width: 100%;
    height: 100%;
    object-fit: cover;
    transition: transform var(--transition);
}

.editorial-card:hover .editorial-image img {
    transform: scale(1.05);
}

.editorial-content {
    padding: var(--spacing-md);
    display: flex;
    flex-direction: column;
}

.editorial-category {
    font-size: 0.75rem;
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    color: var(--color-accent);
    margin-bottom: var(--spacing-xs);
}

.editorial-title {
    font-size: 1.25rem;
    margin-bottom: var(--spacing-sm);
    line-height: 1.4;
}

.editorial-excerpt {
    font-size: 0.95rem;
    color: var(--color-text-light);
    margin-bottom: var(--spacing-md);
    flex-grow: 1;
}

.read-more {
    font-weight: 600;
    color: var(--color-primary);
    display: inline-flex;
    align-items: center;
    gap: var(--spacing-xs);
    transition: all var(--transition);
}

.read-more:hover {
    color: var(--color-accent);
}

/* ===========================
   Newsletter Section
   =========================== */

.newsletter-section {
    background: linear-gradient(135deg, var(--color-primary) 0%, #3a3a3a 100%);
    color: #fff;
    padding: var(--spacing-2xl) var(--spacing-md);
}

.newsletter-container {
    max-width: 600px;
    text-align: center;
}

.newsletter-section h2 {
    color: #fff;
    margin-bottom: var(--spacing-md);
}

.newsletter-section > div > p {
    color: #f0f0f0;
    margin-bottom: var(--spacing-lg);
}

.newsletter-form {
    display: flex;
    gap: var(--spacing-sm);
    flex-wrap: wrap;
    justify-content: center;
    align-items: flex-start;
}

.newsletter-form input {
    flex: 1;
    min-width: 250px;
    padding: var(--spacing-sm) var(--spacing-md);
    border: 1px solid rgba(255, 255, 255, 0.3);
    border-radius: 4px;
    background-color: rgba(255, 255, 255, 0.1);
    color: #fff;
    font-size: 1rem;
}

.newsletter-form input::placeholder {
    color: rgba(255, 255, 255, 0.7);
}

.newsletter-form input:focus-visible {
    outline: 2px solid var(--color-accent);
    outline-offset: 2px;
    background-color: rgba(255, 255, 255, 0.15);
}

.newsletter-note {
    font-size: 0.875rem;
    color: rgba(255, 255, 255, 0.8);
    margin: var(--spacing-md) 0 0;
    width: 100%;
}

/* ===========================
   Footer
   =========================== */

.site-footer {
    background-color: var(--color-primary);
    color: #f0f0f0;
    padding: var(--spacing-2xl) var(--spacing-md) var(--spacing-lg);
}

.footer-container {
    max-width: 1200px;
    margin: 0 auto;
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
    gap: var(--spacing-lg);
    margin-bottom: var(--spacing-2xl);
}

.footer-section h3 {
    color: #fff;
    font-size: 1rem;
    margin-bottom: var(--spacing-md);
}

.footer-section p {
    color: #f0f0f0;
    font-size: 0.95rem;
}

.footer-section ul {
    list-style: none;
}

.footer-section li {
    margin-bottom: var(--spacing-sm);
}

.footer-section a {
    color: #f0f0f0;
    font-size: 0.95rem;
    transition: color var(--transition);
}

.footer-section a:hover {
    color: var(--color-accent);
}

.social-links {
    display: flex;
    gap: var(--spacing-md);
}

.footer-bottom {
    text-align: center;
    padding-top: var(--spacing-lg);
    border-top: 1px solid rgba(255, 255, 255, 0.1);
    color: #f0f0f0;
    font-size: 0.95rem;
}

/* ===========================
   Responsive Design
   =========================== */

@media (max-width: 768px) {
    h1 { font-size: 2rem; }
    h2 { font-size: 1.5rem; }

    .menu-toggle {
        display: flex;
    }

    .nav-menu {
        position: fixed;
        top: 60px;
        left: -100%;
        width: 100%;
        flex-direction: column;
        background-color: #fff;
        border-bottom: 1px solid var(--color-border);
        gap: 0;
        transition: left var(--transition);
        z-index: 40;
    }

    .nav-menu.active {
        left: 0;
    }

    .nav-link {
        width: 100%;
        padding: var(--spacing-md);
        border-bottom: 1px solid var(--color-border);
    }

    .header-container {
        gap: var(--spacing-md);
    }

    .hero-content h2 {
        font-size: 2rem;
    }

    .hero-content p {
        font-size: 1rem;
    }

    .hero {
        min-height: 300px;
        padding: var(--spacing-lg) var(--spacing-md);
    }

    .products-grid {
