    .deals-section,
    .editorial-section {
        padding: var(--spacing-lg) var(--spacing-md);
    }

    .newsletter-form {
        flex-direction: column;
    }

    .newsletter-form input {
        min-width: unset;
        width: 100%;
    }

    .newsletter-form button {
        width: 100%;
    }
}

