    h1 { font-size: 1.5rem; }
    h2 { font-size: 1.25rem; }
    h3 { font-size: 1rem; }

    .logo h1 {
        font-size: 1.25rem;
    }

    .header-actions {
        gap: var(--spacing-sm);
    }

    .hero-content h2 {
        font-size: 1.5rem;
    }

    .hero-content p {
        font-size: 0.95rem;
    }

    .products-grid,
    .deals-grid,
    .editorial-grid {
        grid-template-columns: 1fr;
    }

    .btn {
        padding: var(--spacing-sm) var(--spacing-md);
        font-size: 0.95rem;
    }

    .footer-container {
        grid-template-columns: 1fr;
    }
}

/* ===========================
   High Contrast Mode
   =========================== */

@media (forced-colors: active) {
    .btn-primary {
        border: 2px solid ButtonBorder;
    }

    .btn-outline {
        border: 2px solid ButtonBorder;
    }

    .product-card,
    .deal-card,
    .editorial-card {
        border: 1px solid ButtonBorder;
    }

    a {
        text-decoration: underline;
    }

    .deal-badge {
        border: 1px solid ButtonBorder;
    }

    .skip-link {
        outline: 2px solid ButtonBorder;
    }
}

// ===========================
// Mobile Menu Toggle
// ===========================

const menuToggle = document.querySelector('.menu-toggle');
const navMenu = document.querySelector('.nav-menu');
const navLinks = document.querySelectorAll('.nav-link');

menuToggle.addEventListener('click', () => {
    const isExpanded = menuToggle.getAttribute('aria-expanded') === 'true';
    menuToggle.setAttribute('aria-expanded', !isExpanded);
    navMenu.classList.toggle('active');
});

// Close menu when clicking on a link
navLinks.forEach(link => {
    link.addEventListener('click', () => {
        menuToggle.setAttribute('aria-expanded', 'false');
        navMenu.classList.remove('active');
    });
});

// Close menu when clicking outside
document.addEventListener('click', (e) => {
    if (!e.target.closest('.primary-nav') && !e.target.closest('.menu-toggle')) {
        menuToggle.setAttribute('aria-expanded', 'false');
        navMenu.classList.remove('active');
    }
});

// Close menu with Escape key
document.addEventListener('keydown', (e) => {
    if (e.key === 'Escape') {
        menuToggle.setAttribute('aria-expanded', 'false');
        navMenu.classList.remove('active');
    }
});

// ===========================
// Add to Cart Button Handler
// ===========================

const addToCartButtons = document.querySelectorAll('.btn-add-to-cart');

addToCartButtons.forEach(button => {
    button.addEventListener('click', (e) => {
        e.preventDefault();

        const productCard = button.closest('.product-card');
        const productName = productCard.querySelector('.product-name').textContent;
        const price = productCard.querySelector('.price').textContent;

        // Show feedback
        const originalText = button.textContent;
        button.textContent = '✓ Added to Cart';
        button.disabled = true;

        // Announce to screen readers
        const announcement = document.createElement('div');
        announcement.className = 'sr-only';
        announcement.setAttribute('role', 'status');
        announcement.setAttribute('aria-live', 'polite');
        announcement.textContent = `${productName} at ${price} has been added to cart`;
        document.body.appendChild(announcement);

        setTimeout(() => {
            button.textContent = originalText;
            button.disabled = false;
            announcement.remove();
        }, 2000);
    });
});

// ===========================
// Shop Deal Button Handler
// ===========================

const shopDealButtons = document.querySelectorAll('.deals-section .btn-outline');

shopDealButtons.forEach(button => {
    button.addEventListener('click', (e) => {
        e.preventDefault();

        const dealCard = button.closest('.deal-card');
        const dealName = dealCard.querySelector('.deal-name').textContent;
        const discount = dealCard.querySelector('.deal-badge').textContent;

        // Show feedback
        const originalText = button.textContent;
        button.textContent = '✓ Viewing Deal';
        button.disabled = true;

        // Announce to screen readers
        const announcement = document.createElement('div');
        announcement.className = 'sr-only';
        announcement.setAttribute('role', 'status');
        announcement.setAttribute('aria-live', 'polite');
        announcement.textContent = `Now viewing ${dealName} deal with ${discount} off`;
        document.body.appendChild(announcement);

        setTimeout(() => {
            button.textContent = originalText;
            button.disabled = false;
            announcement.remove();
        }, 1500);
    });
});

// ===========================
// Newsletter Form Handler
// ===========================

const newsletterForm = document.querySelector('.newsletter-form');

newsletterForm.addEventListener('submit', (e) => {
    e.preventDefault();

    const emailInput = newsletterForm.querySelector('input[type="email"]');
    const email = emailInput.value;

    if (!email) {
        alert('Please enter a valid email address');
        return;
    }

    // Show success message
    const button = newsletterForm.querySelector('button');
    const originalText = button.textContent;

    button.textContent = '✓ Subscribed!';
    button.disabled = true;
    emailInput.disabled = true;

    // Announce to screen readers
    const announcement = document.createElement('div');
    announcement.className = 'sr-only';
    announcement.setAttribute('role', 'status');
    announcement.setAttribute('aria-live', 'polite');
    announcement.textContent = `Successfully subscribed to newsletter with email ${email}`;
    document.body.appendChild(announcement);

    setTimeout(() => {
        emailInput.value = '';
        emailInput.disabled = false;
        button.textContent = originalText;
        button.disabled = false;
        announcement.remove();
    }, 2500);
});

// ===========================
// Read Article Link Handler
// ===========================

const readMoreLinks = document.querySelectorAll('.read-more');

readMoreLinks.forEach(link => {
    link.addEventListener('click', (e) => {
        e.preventDefault();

        const article = link.closest('.editorial-card');
        const title = article.querySelector('.editorial-title').textContent;

        // Create announcement for screen readers
        const announcement = document.createElement('div');
        announcement.className = 'sr-only';
        announcement.setAttribute('role', 'status');
        announcement.setAttribute('aria-live', 'polite');
        announcement.textContent = `Loading article: ${title}`;
        document.body.appendChild(announcement);

        // Simulate loading article
        setTimeout(() => {
            announcement.textContent = `Article ${title} is now displayed`;
        }, 1000);

        setTimeout(() => {
            announcement.remove();
        }, 2000);
    });
});

// ===========================
// Search Button Handler
// ===========================

const searchButton = document.querySelector('[aria-label="Search"]');

searchButton.addEventListener('click', () => {
    const announcement = document.createElement('div');
    announcement.className = 'sr-only';
    announcement.setAttribute('role', 'status');
    announcement.setAttribute('aria-live', 'polite');
    announcement.textContent = 'Search functionality is available';
    document.body.appendChild(announcement);

    setTimeout(() => {
        announcement.remove();
    }, 1500);
});

// ===========================
// Shopping Cart Button Handler
// ===========================

const cartButton = document.querySelector('[aria-label="Shopping cart"]');

cartButton.addEventListener('click', () => {
    const announcement = document.createElement('div');
    announcement.className = 'sr-only';
    announcement.setAttribute('role', 'status');
    announcement.setAttribute('aria-live', 'polite');
    announcement.textContent = 'Opening shopping cart';
    document.body.appendChild(announcement);

    setTimeout(() => {
        announcement.remove();
    }, 1500);
});

// ===========================
// Smooth Scroll for Anchor Links
// ===========================

document.querySelectorAll('a[href^="#"]').forEach(anchor => {
    anchor.addEventListener('click', function (e) {
        const href = this.getAttribute('href');

        // Allow skip link to work normally
        if (href === '#main-content') {
            return;
        }

        e.preventDefault();
        const target = document.querySelector(href);

        if (target) {
            target.scrollIntoView({
                behavior: 'smooth',
                block: 'start'
            });

            // Focus management
            target.focus({ preventScroll: true });
        }
    });
});

// ===========================
// Keyboard Navigation for Featured Products
// ===========================

const productCards = document.querySelectorAll('.product-card');

productCards.forEach((card, index) => {
    const button = card.querySelector('.btn-add-to-cart');

    button.addEventListener('keydown', (e) => {
        if (e.key === 'ArrowRight' && index < productCards.length - 1) {
            e.preventDefault();
            productCards[index + 1].querySelector('.btn-add-to-cart').focus();
        } else if (e.key === 'ArrowLeft' && index > 0) {
            e.preventDefault();
            productCards[index - 1].querySelector('.btn-add-to-cart').focus();
        }
    });
});

// ===========================
// Page Load Initialization
// ===========================

document.addEventListener('DOMContentLoaded', () => {
    // Announce page load to screen readers
    const announcement = document.createElement('div');
    announcement.className = 'sr-only';
    announcement.setAttribute('role', 'status');
    announcement.setAttribute('aria-live', 'polite');
    announcement.textContent = 'StyleHub home page loaded. Featured products available';
    document.body.appendChild(announcement);

    setTimeout(() => {
        announcement.remove();
    }, 2000);
});

// ===========================
// Lazy Loading for Images (Optional Enhancement)
// ===========================

if ('IntersectionObserver' in window) {
    const images = document.querySelectorAll('img');
    const imageObserver = new IntersectionObserver((entries) => {
        entries.forEach(entry => {
            if (entry.isIntersecting) {
                const img = entry.target;
                img.style.opacity = '1';
                imageObserver.unobserve(img);
            }
        });
    });

    images.forEach(img => {
        img.style.opacity = '0.7';
        img.style.transition = 'opacity 0.3s ease';
        imageObserver.observe(img);
    });
}

