+    z-index: 10;
+}
+
+.deal-image {
+    width: 100%;
+    aspect-ratio: 1;
+    background-color: #f5f5f5;
+    overflow: hidden;
+}
+
+.deal-image img {
+    width: 100%;
+    height: 100%;
+    object-fit: cover;
+    transition: transform var(--transition);
+}
+
+.deal-card:hover .deal-image img {
+    transform: scale(1.1);
+}
+
+.deal-info {
+    padding: var(--spacing-md);
+}
+
+.deal-name {
+    font-size: 1rem;
+    font-weight: 600;
+    margin-bottom: var(--spacing-sm);
+}
+
+.deal-pricing {
+    display: flex;
+    gap: var(--spacing-sm);
+    align-items: center;
+    margin-bottom: var(--spacing-md);
+}
+
+.price-original {
+    color: var(--color-text-light);
+    text-decoration: line-through;
+    font-size: 0.9rem;
+}
+
+.price-sale {
+    font-size: 1.25rem;
+    font-weight: 600;
+    color: var(--color-danger);
+}
+
+/* ===========================
+   Editorial Section
+   =========================== */
+
+.editorial-section {
+    padding: var(--spacing-2xl) var(--spacing-md);
+}
+
+.editorial-grid {
+    display: grid;
+    grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
+    gap: var(--spacing-lg);
+}
+
+.editorial-card {
+    background: #fff;
+    border-radius: 8px;
+    overflow: hidden;
+    transition: all var(--transition);
+    box-shadow: var(--shadow-sm);
+    border: 1px solid var(--color-border);
+}
+
+.editorial-card:hover {
+    box-shadow: var(--shadow-lg);
+}
+
+.editorial-image {
+    width: 100%;
+    aspect-ratio: 4 / 3;
+    overflow: hidden;
+    background-color: var(--color-secondary);
+}
+
+.editorial-image img {
+    width: 100%;
+    height: 100%;
+    object-fit: cover;
+    transition: transform var(--transition);
+}
+
+.editorial-card:hover .editorial-image img {
+    transform: scale(1.05);
+}
+
+.editorial-content {
+    padding: var(--spacing-md);
+    display: flex;
+    flex-direction: column;
+}
+
+.editorial-category {
