+}
+
+.newsletter-form input:focus-visible {
+    outline: 2px solid var(--color-accent);
+    outline-offset: 2px;
+    background-color: rgba(255, 255, 255, 0.15);
+}
+
+.newsletter-note {
+    font-size: 0.875rem;
+    color: rgba(255, 255, 255, 0.8);
+    margin: var(--spacing-md) 0 0;
+    width: 100%;
+}
+
+/* ===========================
+   Footer
+   =========================== */
+
+.site-footer {
+    background-color: var(--color-primary);
+    color: #f0f0f0;
+    padding: var(--spacing-2xl) var(--spacing-md) var(--spacing-lg);
+}
+
+.footer-container {
+    max-width: 1200px;
+    margin: 0 auto;
+    display: grid;
+    grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
+    gap: var(--spacing-lg);
+    margin-bottom: var(--spacing-2xl);
+}
+
+.footer-section h3 {
+    color: #fff;
+    font-size: 1rem;
+    margin-bottom: var(--spacing-md);
+}
+
+.footer-section p {
+    color: #f0f0f0;
+    font-size: 0.95rem;
+}
+
+.footer-section ul {
+    list-style: none;
+}
+
+.footer-section li {
+    margin-bottom: var(--spacing-sm);
+}
+
+.footer-section a {
+    color: #f0f0f0;
+    font-size: 0.95rem;
+    transition: color var(--transition);
+}
+
+.footer-section a:hover {
+    color: var(--color-accent);
+}
+
+.social-links {
+    display: flex;
+    gap: var(--spacing-md);
+}
+
+.footer-bottom {
+    text-align: center;
+    padding-top: var(--spacing-lg);
+    border-top: 1px solid rgba(255, 255, 255, 0.1);
+    color: #f0f0f0;
+    font-size: 0.95rem;
+}
+
+/* ===========================
+   Responsive Design
+   =========================== */
+
+@media (max-width: 768px) {
+    h1 { font-size: 2rem; }
+    h2 { font-size: 1.5rem; }
+    
+    .menu-toggle {
+        display: flex;
+    }
+
+    .nav-menu {
+        position: fixed;
+        top: 60px;
+        left: -100%;
+        width: 100%;
+        flex-direction: column;
+        background-color: #fff;
+        border-bottom: 1px solid var(--color-border);
+        gap: 0;
+        transition: left var(--transition);
+        z-index: 40;
+    }
+
+    .nav-menu.active {
+        left: 0;
+    }
+
+    .nav-link {
+        width: 100%;
+        padding: var(--spacing-md);
+        border-bottom: 1px solid var(--color-border);
+    }
+
+    .header-container {
+        gap: var(--spacing-md);
+    }
+
+    .hero-content h2 {
+        font-size: 2rem;
+    }
+
+    .hero-content p {
+        font-size: 1rem;
+    }
+
+    .hero {
+        min-height: 300px;
+        padding: var(--spacing-lg) var(--spacing-md);
+    }
+
+    .products-grid {
+        grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
+    }
+
+    .section-title {
+        font-size: 1.5rem;
+        margin-bottom: var(--spacing-lg);
+    }
+
+    .featured-section,
+    .deals-section,
