+    }
+
+    h1 { font-size: 1.5rem; }
+    h2 { font-size: 1.25rem; }
+    h3 { font-size: 1rem; }
+
+    .logo h1 {
+        font-size: 1.25rem;
+    }
+
+    .header-actions {
+        gap: var(--spacing-sm);
+    }
+
+    .hero-content h2 {
+        font-size: 1.5rem;
+    }
+
