}

.logo h1 {
    font-size: 1.5rem;
    margin: 0;
    letter-spacing: -0.02em;
}

.primary-nav {
    flex: 1;
}

.menu-toggle {
    display: none;
    background: none;
    border: none;
    cursor: pointer;
    padding: var(--spacing-xs);
    color: var(--color-primary);
    min-height: 44px;
    min-width: 44px;
}

.menu-toggle:focus-visible {
