}

.header-actions {
    display: flex;
    gap: var(--spacing-md);
    align-items: center;
}

/* ===========================
   Hero Section
   =========================== */

.hero {
    background: linear-gradient(135deg, var(--color-secondary) 0%, #f0e8e0 100%);
    padding: var(--spacing-2xl) var(--spacing-md);
    text-align: center;
    min-height: 400px;
    display: flex;
    align-items: center;
    justify-content: center;
}

.hero-content h2 {
    font-size: 3rem;
    margin-bottom: var(--spacing-md);
    color: var(--color-primary);
}

.hero-content p {
    font-size: 1.25rem;
    margin-bottom: var(--spacing-lg);
    color: var(--color-text-light);
    max-width: 500px;
    margin-left: auto;
    margin-right: auto;
}

/* ===========================
   Products Grid
   =========================== */

.featured-section {
    padding: var(--spacing-2xl) var(--spacing-md);
}

.products-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
    gap: var(--spacing-lg);
}

.product-card {
    background: #fff;
    border: 1px solid var(--color-border);
    border-radius: 8px;
    overflow: hidden;
    transition: all var(--transition);
    display: flex;
    flex-direction: column;
    height: 100%;
}

.product-card:hover {
