    display: flex;
    flex-direction: column;
    flex: 1;
}

.product-name {
    font-size: 1.1rem;
    margin-bottom: var(--spacing-xs);
    font-weight: 600;
}

.product-category {
    font-size: 0.875rem;
    color: var(--color-text-light);
    margin-bottom: var(--spacing-sm);
}

.product-rating {
    display: flex;
    align-items: center;
    gap: var(--spacing-xs);
    margin-bottom: var(--spacing-sm);
    font-size: 0.875rem;
}

.stars {
    color: var(--color-accent);
    letter-spacing: 2px;
}

.rating-count {
    color: var(--color-text-light);
}

.product-pricing {
    margin-bottom: var(--spacing-md);
    flex-grow: 1;
    display: flex;
    align-items: flex-end;
}

.price {
    font-size: 1.25rem;
    font-weight: 600;
    color: var(--color-primary);
}

.btn-add-to-cart {
    width: 100%;
}

/* ===========================
   Deals Section
   =========================== */

.deals-section {
    padding: var(--spacing-2xl) var(--spacing-md);
    background-color: var(--color-secondary);
}

.deals-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
    gap: var(--spacing-lg);
}

.deal-card {
    background: #fff;
    border-radius: 8px;
    overflow: hidden;
    position: relative;
    transition: all var(--transition);
    box-shadow: var(--shadow-sm);
}

.deal-card:hover {
    box-shadow: var(--shadow-lg);
    transform: translateY(-4px);
}

.deal-badge {
    position: absolute;
    top: var(--spacing-sm);
    right: var(--spacing-sm);
    background-color: var(--color-danger);
    color: #fff;
    padding: var(--spacing-xs) var(--spacing-sm);
    border-radius: 4px;
    font-weight: 600;
    z-index: 10;
}

.deal-image {
    width: 100%;
    aspect-ratio: 1;
    background-color: #f5f5f5;
    overflow: hidden;
}

.deal-image img {
    width: 100%;
    height: 100%;
    object-fit: cover;
    transition: transform var(--transition);
}

.deal-card:hover .deal-image img {
    transform: scale(1.1);
}

.deal-info {
    padding: var(--spacing-md);
}

.deal-name {
    font-size: 1rem;
    font-weight: 600;
    margin-bottom: var(--spacing-sm);
}

.deal-pricing {
    display: flex;
    gap: var(--spacing-sm);
    align-items: center;
    margin-bottom: var(--spacing-md);
}

.price-original {
    color: var(--color-text-light);
    text-decoration: line-through;
    font-size: 0.9rem;
}

.price-sale {
    font-size: 1.25rem;
    font-weight: 600;
    color: var(--color-danger);
}

/* ===========================
   Editorial Section
   =========================== */

.editorial-section {
    padding: var(--spacing-2xl) var(--spacing-md);
}

.editorial-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
    gap: var(--spacing-lg);
}

.editorial-card {
    background: #fff;
    border-radius: 8px;
    overflow: hidden;
    transition: all var(--transition);
    box-shadow: var(--shadow-sm);
    border: 1px solid var(--color-border);
}

.editorial-card:hover {
    box-shadow: var(--shadow-lg);
}

.editorial-image {
    width: 100%;
    aspect-ratio: 4 / 3;
    overflow: hidden;
    background-color: var(--color-secondary);
}

.editorial-image img {
    width: 100%;
    height: 100%;
    object-fit: cover;
    transition: transform var(--transition);
}

.editorial-card:hover .editorial-image img {
    transform: scale(1.05);
}

.editorial-content {
    padding: var(--spacing-md);
    display: flex;
    flex-direction: column;
}

.editorial-category {
    font-size: 0.75rem;
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    color: var(--color-accent);
    margin-bottom: var(--spacing-xs);
}

.editorial-title {
    font-size: 1.25rem;
    margin-bottom: var(--spacing-sm);
    line-height: 1.4;
}

.editorial-excerpt {
    font-size: 0.95rem;
    color: var(--color-text-light);
    margin-bottom: var(--spacing-md);
    flex-grow: 1;
}

.read-more {
    font-weight: 600;
    color: var(--color-primary);
    display: inline-flex;
    align-items: center;
    gap: var(--spacing-xs);
    transition: all var(--transition);
}

.read-more:hover {
    color: var(--color-accent);
}

/* ===========================
   Newsletter Section
   =========================== */

.newsletter-section {
    background: linear-gradient(135deg, var(--color-primary) 0%, #3a3a3a 100%);
    color: #fff;
    padding: var(--spacing-2xl) var(--spacing-md);
}

.newsletter-container {
    max-width: 600px;
    text-align: center;
}

.newsletter-section h2 {
    color: #fff;
    margin-bottom: var(--spacing-md);
}

.newsletter-section > div > p {
    color: #f0f0f0;
    margin-bottom: var(--spacing-lg);
}

.newsletter-form {
    display: flex;
    gap: var(--spacing-sm);
    flex-wrap: wrap;
    justify-content: center;
    align-items: flex-start;
}

.newsletter-form input {
    flex: 1;
    min-width: 250px;
    padding: var(--spacing-sm) var(--spacing-md);
    border: 1px solid rgba(255, 255, 255, 0.3);
    border-radius: 4px;
    background-color: rgba(255, 255, 255, 0.1);
    color: #fff;
    font-size: 1rem;
}

.newsletter-form input::placeholder {
    color: rgba(255, 255, 255, 0.7);
}

.newsletter-form input:focus-visible {
    outline: 2px solid var(--color-accent);
    outline-offset: 2px;
    background-color: rgba(255, 255, 255, 0.15);
}

.newsletter-note {
    font-size: 0.875rem;
    color: rgba(255, 255, 255, 0.8);
    margin: var(--spacing-md) 0 0;
    width: 100%;
}

/* ===========================
   Footer
   =========================== */

.site-footer {
    background-color: var(--color-primary);
    color: #f0f0f0;
    padding: var(--spacing-2xl) var(--spacing-md) var(--spacing-lg);
}

.footer-container {
    max-width: 1200px;
    margin: 0 auto;
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
    gap: var(--spacing-lg);
    margin-bottom: var(--spacing-2xl);
}

.footer-section h3 {
    color: #fff;
    font-size: 1rem;
    margin-bottom: var(--spacing-md);
}

.footer-section p {
    color: #f0f0f0;
    font-size: 0.95rem;
}

.footer-section ul {
    list-style: none;
}

.footer-section li {
    margin-bottom: var(--spacing-sm);
}

.footer-section a {
    color: #f0f0f0;
    font-size: 0.95rem;
    transition: color var(--transition);
}

.footer-section a:hover {
    color: var(--color-accent);
}

.social-links {
    display: flex;
    gap: var(--spacing-md);
}

.footer-bottom {
    text-align: center;
    padding-top: var(--spacing-lg);
    border-top: 1px solid rgba(255, 255, 255, 0.1);
    color: #f0f0f0;
    font-size: 0.95rem;
}

/* ===========================
   Responsive Design
   =========================== */

@media (max-width: 768px) {
    h1 { font-size: 2rem; }
    h2 { font-size: 1.5rem; }

    .menu-toggle {
        display: flex;
    }

    .nav-menu {
        position: fixed;
        top: 60px;
        left: -100%;
        width: 100%;
        flex-direction: column;
        background-color: #fff;
        border-bottom: 1px solid var(--color-border);
        gap: 0;
        transition: left var(--transition);
        z-index: 40;
    }

    .nav-menu.active {
        left: 0;
    }

    .nav-link {
        width: 100%;
        padding: var(--spacing-md);
        border-bottom: 1px solid var(--color-border);
    }

    .header-container {
        gap: var(--spacing-md);
    }

    .hero-content h2 {
        font-size: 2rem;
    }

    .hero-content p {
        font-size: 1rem;
    }

    .hero {
        min-height: 300px;
        padding: var(--spacing-lg) var(--spacing-md);
    }

    .products-grid {
        grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
    }

    .section-title {
        font-size: 1.5rem;
        margin-bottom: var(--spacing-lg);
    }

    .featured-section,
    .deals-section,
    .editorial-section {
        padding: var(--spacing-lg) var(--spacing-md);
    }

    .newsletter-form {
        flex-direction: column;
    }

    .newsletter-form input {
        min-width: unset;
        width: 100%;
    }

    .newsletter-form button {
        width: 100%;
    }
}

@media (max-width: 480px) {
    :root {
        --spacing-md: 1rem;
        --spacing-lg: 1.5rem;
        --spacing-xl: 2rem;
        --spacing-2xl: 2.5rem;
    }

    h1 { font-size: 1.5rem; }
    h2 { font-size: 1.25rem; }
    h3 { font-size: 1rem; }

    .logo h1 {
        font-size: 1.25rem;
    }

    .header-actions {
        gap: var(--spacing-sm);
    }

    .hero-content h2 {
        font-size: 1.5rem;
    }

    .hero-content p {
        font-size: 0.95rem;
    }

    .products-grid,
    .deals-grid,
    .editorial-grid {
        grid-template-columns: 1fr;
    }

    .btn {
        padding: var(--spacing-sm) var(--spacing-md);
        font-size: 0.95rem;
    }

    .footer-container {
        grid-template-columns: 1fr;
    }
}

/* ===========================
   High Contrast Mode
   =========================== */

@media (forced-colors: active) {
    .btn-primary {
        border: 2px solid ButtonBorder;
    }

    .btn-outline {
        border: 2px solid ButtonBorder;
    }

    .product-card,
    .deal-card,
    .editorial-card {
        border: 1px solid ButtonBorder;
    }

    a {
        text-decoration: underline;
    }

    .deal-badge {
        border: 1px solid ButtonBorder;
    }

    .skip-link {
        outline: 2px solid ButtonBorder;
    }
}
